// 7. AI Tutor Interactive Lesson Widget
function AITutor() {
  const [messages, setMessages] = useState([
    { sender: 'tutor', text: "Hi! Let's reflect on Outcome-Based Education. What is the main outcome of your course?" }
  ]);
  const [input, setInput] = useState('');

  const handleSend = () => {
    if (!input.trim()) return;
    const userMsg = input.trim();
    setMessages(prev => [...prev, { sender: 'user', text: userMsg }]);
    setInput('');

    setTimeout(() => {
      setMessages(prev => [
        ...prev,
        { sender: 'tutor', text: "Great point. In standard pedagogy, we evaluate that outcome through project artifacts. Have you structured your portfolio checks yet?" }
      ]);
    }, 1000);
  };

  return (
    <div className="p-5 rounded-2xl border border-slate-800 bg-slate-950/60 my-6 text-left animate-fade-up flex flex-col h-[280px]">
      <div className="text-xs font-bold text-sky-400 uppercase tracking-wider mb-2 flex items-center gap-2">
        <Sparkles className="h-4 w-4 text-sky-400" /> AI Reflection Tutor
      </div>
      
      <div className="flex-1 overflow-y-auto space-y-3 pr-2 mb-3">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`p-2.5 rounded-xl max-w-[85%] text-xs leading-relaxed ${
              msg.sender === 'user' 
                ? 'bg-sky-500/10 border border-sky-500/20 text-sky-300' 
                : 'bg-slate-900/60 border border-slate-800 text-slate-300'
            }`}>
              {msg.text}
            </div>
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <input 
          type="text" value={input} onChange={(e) => setInput(e.target.value)}
          placeholder="Type your response..." 
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          className="flex-1 bg-slate-900 border border-slate-850 rounded-lg px-3 py-1.5 text-xs text-slate-200 outline-none focus:border-sky-400"
        />
        <button onClick={handleSend} className="bg-sky-400 hover:bg-sky-500 text-slate-950 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors">
          Send
        </button>
      </div>
    </div>
  );
}

// === COMPONENT RESOLVER ===
function renderSlideContent(html) {
  if (!html) return null;

  // 1. Hydrate Chart Markers
  if (html.includes('class="chart-hydration-marker"')) {
    const markerRegex = /<div\s+class="chart-hydration-marker"\s+data-chart-type="([^"]+)"\s+data-dataset="([^"]+)"\s+data-x="([^"]+)"\s+data-y="([^"]+)"\s*>\s*<\/div>/;
    const match = html.match(markerRegex);
    if (match) {
      const parts = html.split(match[0]);
      return (
        <>
          {renderSlideContent(parts[0])}
          <ChartComponent 
            type={match[1]} 
            dataset={match[2]} 
            x={match[3]} 
            y={match[4]} 
          />
          {parts[1] && renderSlideContent(parts[1])}
        </>
      );
    }
  }

  // 1.5. Hydrate ExerciseLauncher with dynamic props
  const launcherMatch = html.match(/<ExerciseLauncher\s+([^>]+)\s*\/?>/i);
  if (launcherMatch) {
    const attrsStr = launcherMatch[1];
    
    // Parse attributes safely using regexes
    const urlMatch = attrsStr.match(/url="([^"]+)"/i);
    const titleMatch = attrsStr.match(/title="([^"]+)"/i);
    const instMatch = attrsStr.match(/instructions="([^"]+)"/i);
    
    const url = urlMatch ? urlMatch[1] : '';
    const title = titleMatch ? titleMatch[1] : 'Interactive Exercise';
    const instructions = instMatch ? instMatch[1] : '';
    
    const parts = html.split(/<ExerciseLauncher\s+[^>]+\s*\/?>/i);
    return (
      <>
        {renderSlideContent(parts[0])}
        <ExerciseLauncher url={url} title={title} instructions={instructions} />
        {parts[1] && renderSlideContent(parts[1])}
      </>
    );
  }

  // 2. Hydrate dynamic registry widgets recursively
  const widgets = [
    { tag: /<ROIWidget\s*\/?>/, component: <ROIWidget /> },
    { tag: /<EnrollmentCalculator\s*\/?>/, component: <EnrollmentCalculator /> },
    { tag: /<AskAI\s*\/?>/, component: <AskAI /> },
    { tag: /<SimulationEngine\s*\/?>/, component: <SimulationEngine /> },
    { tag: /<InteractiveTimeline\s*\/?>/, component: <InteractiveTimeline /> },
    { tag: /<AITutor\s*\/?>/, component: <AITutor /> },
    { tag: /<AIVivaLauncher\s*\/?>/, component: <AIVivaLauncher vivaUrl={presentationData.aiVivaUrl} /> }
  ];

  for (const widget of widgets) {
    if (html.match(widget.tag)) {
      const parts = html.split(widget.tag);
      return (
        <>
          {renderSlideContent(parts[0])}
          {widget.component}
          {parts[1] && renderSlideContent(parts[1])}
        </>
      );
    }
  }

  return <div dangerouslySetInnerHTML={{ __html: html }} />;
}

// === MAIN COMPONENT ===
function App() {
  const { title, author, affiliation, date, tagline, slides } = presentationData;
  
  const [currentSlide, setCurrentSlide] = useState(0);
  const [sidebarWidth, setSidebarWidth] = useState(320);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [theme, setTheme] = useState('dark');
  
  // I18n state
  const [lang, setLang] = useState('en');
  
  // Progress State
  const [progress, setProgress] = useState(() => {
    const key = `slide_progress_${title.replace(/\s+/g, '_')}`;
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : {
      startedAt: new Date().toISOString(),
      completedAt: null,
      visitedSlides: [0]
    };
  });
  
  // Sync progress effect
  useEffect(() => {
    const key = `slide_progress_${title.replace(/\s+/g, '_')}`;
    setProgress(prev => {
      const visited = prev.visitedSlides.includes(currentSlide) 
        ? prev.visitedSlides 
        : [...prev.visitedSlides, currentSlide].sort((a, b) => a - b);
      
      const completedAt = (currentSlide === slides.length - 1 && !prev.completedAt) 
        ? new Date().toISOString() 
        : prev.completedAt;
        
      const next = {
        ...prev,
        visitedSlides: visited,
        completedAt
      };
      localStorage.setItem(key, JSON.stringify(next));
      return next;
    });
  }, [currentSlide, slides.length, title]);

  // Sync lang effect
  useEffect(() => {
    document.documentElement.setAttribute('data-lang', lang);
  }, [lang]);

  // Dynamic LaTeX Math (KaTeX) and Mermaid Diagram Rendering on Slide transitions
  useEffect(() => {
    const timer = setTimeout(() => {
      // 1. Render Math equations
      if (window.renderMathInElement) {
        window.renderMathInElement(document.body, {
          delimiters: [
            { left: '$$', right: '$$', display: true },
            { left: '$', right: '$', display: false }
          ],
          throwOnError: false
        });
      }
      
      // 2. Render Mermaid diagrams
      if (window.mermaid) {
        const codeMermaids = document.querySelectorAll('pre code.language-mermaid, pre.language-mermaid, div.language-mermaid');
        codeMermaids.forEach(el => {
          const container = document.createElement('div');
          container.className = 'mermaid text-center my-4 overflow-x-auto';
          container.textContent = el.textContent.trim();
          const target = el.parentElement && el.parentElement.tagName === 'PRE' ? el.parentElement : el;
          target.replaceWith(container);
        });

        const mermaidElements = document.querySelectorAll('.mermaid');
        if (mermaidElements.length > 0) {
          const unrendered = Array.from(mermaidElements).filter(el => !el.hasAttribute('data-processed'));
          if (unrendered.length > 0) {
            window.mermaid.run({
              nodes: unrendered
            }).catch(err => {
              console.error("Mermaid run error:", err);
            });
          }
        }
      }
    }, 100);
    
    return () => clearTimeout(timer);
  }, [currentSlide]);

  // Timer States
  const [secondsElapsed, setSecondsElapsed] = useState(0); // starts at 0
  const [timerRunning, setTimerRunning] = useState(true);
  
  // IST Clock
  const [istTime, setIstTime] = useState('');
  
  // Dragging state
  const isDragging = useRef(false);

  // Clock Update Effect
  useEffect(() => {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Kolkata',
      hour: 'numeric',
      minute: '2-digit',
      second: '2-digit',
      hour12: true
    });
    const tick = () => setIstTime(fmt.format(new Date()));
    tick();
    const interval = setInterval(tick, 1000);
    return () => clearInterval(interval);
  }, []);

  // Timer Update Effect
  useEffect(() => {
    let interval = null;
    if (timerRunning) {
      interval = setInterval(() => {
        setSecondsElapsed(prev => prev + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [timerRunning]);

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowLeft') previousSlide();
      if (e.key === 'ArrowRight') nextSlide();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSlide]);

  // Expose checkAnswer and switchTab globally for compiled HTML content compatibility
  useEffect(() => {
    window.checkAnswer = function(element, selected, correct) {
      const options = element.parentElement.querySelectorAll('.quiz-option');
      options.forEach(opt => {
        opt.style.pointerEvents = 'none';
        if (opt.textContent.trim().startsWith(correct)) {
          opt.classList.add('correct');
        } else {
          if (opt === element) {
            opt.classList.add('incorrect');
          }
        }
      });
    };

    window.switchTab = function(element, bodyId) {
      const container = element.closest('.tabs-container');
      if (!container) return;
      
      const buttons = container.querySelectorAll('.tab-btn');
      buttons.forEach(btn => {
        btn.classList.remove('active', 'border-sky-400', 'text-sky-400', 'bg-sky-500/10');
        btn.classList.add('border-slate-800', 'text-slate-400');
      });
      
      element.classList.add('active', 'border-sky-400', 'text-sky-400', 'bg-sky-500/10');
      element.classList.remove('border-slate-800', 'text-slate-400');
      
      const bodies = container.querySelectorAll('.tab-body');
      bodies.forEach(body => {
        body.style.display = 'none';
        body.classList.remove('active');
      });
      
      const activeBody = container.querySelector('#' + bodyId);
      if (activeBody) {
        activeBody.style.display = 'block';
        activeBody.classList.add('active');
      }
    };

    window.checkBlank = function(element, correctAnswersStr) {
      const val = element.value.trim().toLowerCase();
      const correctList = correctAnswersStr.split('|').map(a => a.trim().toLowerCase());
      
      // Remove any existing feedback tags next to this element
      const sibling = element.nextElementSibling;
      if (sibling && sibling.classList.contains('blank-feedback')) {
        sibling.remove();
      }
      
      const feedbackSpan = document.createElement('span');
      feedbackSpan.className = 'blank-feedback ml-1.5 font-sans font-bold text-xs inline-flex items-center gap-1';
      
      if (correctList.includes(val)) {
        element.style.backgroundColor = 'rgba(16, 185, 129, 0.15)';
        element.style.borderColor = '#10b981';
        feedbackSpan.style.color = '#10b981';
        feedbackSpan.innerHTML = '&#10004;'; // checkmark tick
      } else {
        element.style.backgroundColor = 'rgba(244, 63, 94, 0.15)';
        element.style.borderColor = '#f43f5e';
        feedbackSpan.style.color = '#f43f5e';
        const rightResponse = correctAnswersStr.split('|')[0];
        feedbackSpan.innerHTML = `&#10008; <span class="text-slate-400 font-normal">(${rightResponse})</span>`; // cross mark + correct answer
      }
      
      element.parentNode.insertBefore(feedbackSpan, element.nextSibling);
    };

    return () => {
      delete window.checkAnswer;
      delete window.switchTab;
      delete window.checkBlank;
    };
  }, []);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) showSlide(currentSlide + 1);
  };

  const previousSlide = () => {
    if (currentSlide > 0) showSlide(currentSlide - 1);
  };

  const showSlide = (index) => {
    setCurrentSlide(index);
  };

  const formatTimer = () => {
    const mins = Math.floor(secondsElapsed / 60);
    const secs = secondsElapsed % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable fullscreen: ${err.message}`);
      });
    } else {
      document.exitFullscreen();
    }
  };

  // Drag resizing handlers
  const handleMouseDown = (e) => {
    isDragging.current = true;
    document.body.style.cursor = 'col-resize';
    e.preventDefault();
  };

  useEffect(() => {
    const handleMouseMove = (e) => {
      if (!isDragging.current) return;
      const newWidth = e.clientX;
      if (newWidth > 200 && newWidth < 480) {
        setSidebarWidth(newWidth);
      }
    };
    
    const handleMouseUp = () => {
      if (isDragging.current) {
        isDragging.current = false;
        document.body.style.cursor = 'default';
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  // Dot Pagination Truncation
  const renderDots = () => {
    const maxDotsVisible = 9;
    let startDot = 0;
    let endDot = slides.length;
    
    if (slides.length > maxDotsVisible) {
      const half = Math.floor(maxDotsVisible / 2);
      startDot = currentSlide - half;
      endDot = currentSlide + half + 1;
      
      if (startDot < 0) {
        startDot = 0;
        endDot = maxDotsVisible;
      } else if (endDot > slides.length) {
        endDot = slides.length;
        startDot = slides.length - maxDotsVisible;
      }
    }
    
    const dots = [];
    for (let i = startDot; i < endDot; i++) {
      dots.push(
        <div 
          key={i}
          onClick={() => showSlide(i)}
          title={slides[i].title}
          className={`transition-all rounded-full cursor-pointer ${
            i === currentSlide 
              ? "w-2.5 h-2.5 bg-sky-400" 
              : "w-1.5 h-1.5 bg-slate-700 hover:bg-slate-500"
          }`}
        />
      );
    }
    return dots;
  };

  // Group slide indexing for Accordion Topics
  const renderSidebarAccordion = () => {
    const activeTopicIdx = slides[currentSlide].topic_idx;
    const accordionGroups = [];
    let currentTopicIndex = -1;
    let currentSubtopics = [];
    
    slides.forEach((slide, index) => {
      if (slide.is_major) {
        if (currentTopicIndex !== -1) {
          accordionGroups.push({
            topicIdx: currentTopicIndex,
            title: slides[currentTopicIndex].title,
            subtopics: currentSubtopics
          });
        }
        currentTopicIndex = index;
        currentSubtopics = [];
      } else {
        currentSubtopics.push({
          index,
          title: slide.title,
          label: slide.label
        });
      }
    });
    
    // Add final group
    if (currentTopicIndex !== -1) {
      accordionGroups.push({
        topicIdx: currentTopicIndex,
        title: slides[currentTopicIndex].title,
        subtopics: currentSubtopics
      });
    }

    return accordionGroups.map((group) => {
      const isTopicExpanded = group.topicIdx === activeTopicIdx;
      return (
        <div key={group.topicIdx} className="mb-2">
          {/* Topic Title Button */}
          <div 
            onClick={() => showSlide(group.topicIdx)}
            style={{
              borderColor: group.topicIdx === currentSlide ? '#E5A823' : 'transparent',
              background: group.topicIdx === currentSlide ? 'rgba(229, 168, 35, 0.15)' : 'transparent',
              color: group.topicIdx === currentSlide ? '#E5A823' : ''
            }}
            className={`slide-item p-2 rounded-lg text-xs font-semibold cursor-pointer transition-all border flex items-center ${
              group.topicIdx === currentSlide ? "text-sky-400" : "text-slate-200 hover:bg-slate-900/60 hover:text-sky-400"
            }`}
          >
            <Bookmark className="h-3.5 w-3.5 text-sky-400 mr-2 shrink-0" />
            <span>{group.title}</span>
          </div>

          {/* Subtopics List */}
          {isTopicExpanded && group.subtopics.length > 0 && (
            <div className="pl-4 mt-1 space-y-1">
              {group.subtopics.map((sub) => (
                <div 
                  key={sub.index}
                  onClick={() => showSlide(sub.index)}
                  style={{
                    borderColor: sub.index === currentSlide ? '#E5A823' : 'transparent',
                    background: sub.index === currentSlide ? 'rgba(229, 168, 35, 0.15)' : 'transparent',
                    color: sub.index === currentSlide ? '#E5A823' : ''
                  }}
                  className={`slide-item p-1.5 rounded-lg text-xs font-medium cursor-pointer transition-all border flex items-center ${
                    sub.index === currentSlide ? "text-sky-400 font-bold" : "text-slate-400 hover:bg-slate-900/60 hover:text-sky-400"
                  }`}
                >
                  <span className="text-slate-600 mr-2 font-mono text-[10px] shrink-0">{sub.label}</span>
                  <span>{sub.title}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    });
  };

  // Render Slide layout structures dynamically
  const activeSlideData = slides[currentSlide];

  // Memoize slide HTML content rendering to prevent re-creating DOM nodes when timer ticks
  const slideContentNode = useMemo(() => {
    if (currentSlide === 0) return null;
    return renderSlideContent(activeSlideData.content);
  }, [currentSlide, activeSlideData.content]);

  return (
    <div className={`flex h-screen w-screen overflow-hidden ${theme === 'light' ? 'theme-light' : ''} bg-slate-950 text-slate-100`}>
      {/* 1. Sidebar Index Panel */}
      <aside 
        id="sidebar-container" 
        style={{ width: sidebarCollapsed ? 0 : `${sidebarWidth}px`, display: sidebarCollapsed ? 'none' : 'flex' }}
        className="relative bg-slate-950/40 border-r border-slate-800 flex-col z-20 shrink-0 transition-all duration-300"
      >
        {/* Sidebar Brand Header */}
        <div className="p-4 border-b border-slate-800/80 bg-slate-950/60 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="flex items-center justify-center w-9 h-9 rounded-lg bg-sky-500/10 border border-sky-500/20 text-sky-400 text-sm">
              <GraduationCap className="h-5 w-5 text-sky-400" />
            </div>
            <div>
              <div className="text-xs font-bold uppercase tracking-wider text-slate-200">{title}</div>
              <div className="text-[10px] text-sky-400 font-medium">{author}</div>
            </div>
          </div>
          <button 
            onClick={() => setSidebarCollapsed(true)} 
            className="text-slate-500 hover:text-white transition-colors"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
        </div>
        
        {/* Accordion List navigation */}
        <nav className="flex-1 overflow-y-auto p-3.5 space-y-1 select-none">
          {renderSidebarAccordion()}
        </nav>
        
        {/* Student Progress Tracker */}
        <div className="p-4 border-t border-slate-800 bg-slate-950/40 text-left">
          <div className="text-[10px] uppercase tracking-wider text-slate-500 font-mono mb-2 flex items-center justify-between">
            <span>Learning Progress</span>
            <span className="text-sky-400 font-semibold font-mono">
              {Math.round((progress.visitedSlides.length / slides.length) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-800 rounded-full h-1.5 mb-3 overflow-hidden">
            <div 
              className="bg-sky-400 h-1.5 rounded-full transition-all duration-300 animate-pulse"
              style={{ width: `${(progress.visitedSlides.length / slides.length) * 100}%` }}
            />
          </div>
          <div className="text-[9px] text-slate-400 leading-normal mb-2.5">
            <div>Started: <strong className="text-slate-300 font-mono">{new Date(progress.startedAt).toLocaleDateString()}</strong></div>
            {progress.completedAt && (
              <div>Completed: <strong className="text-emerald-400 font-mono">{new Date(progress.completedAt).toLocaleDateString()}</strong></div>
            )}
          </div>
          <button
            onClick={() => {
              const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(progress, null, 2));
              const downloadAnchor = document.createElement('a');
              downloadAnchor.setAttribute("href", dataStr);
              downloadAnchor.setAttribute("download", `progress-${title.toLowerCase().replace(/\s+/g, '-')}.json`);
              document.body.appendChild(downloadAnchor);
              downloadAnchor.click();
              downloadAnchor.remove();
            }}
            className="w-full py-1.5 rounded bg-slate-900 hover:bg-slate-800 border border-slate-800 hover:border-slate-700 text-slate-300 hover:text-white font-bold text-[9px] uppercase tracking-wide transition-all text-center flex items-center justify-center gap-1.5"
          >
            📥 Download Progress
          </button>
        </div>

        {/* Bottom Talk Timer */}
        <div className="p-4 border-t border-slate-800 bg-slate-950/60">
          <div className="text-[10px] uppercase tracking-wider text-slate-500 font-mono mb-2 flex items-center justify-between">
            <span>Talk Timer (Target: 25:00)</span>
            <span className="text-emerald-400 font-semibold flex items-center gap-1 font-mono">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse"></span> Active
            </span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-xs font-mono font-bold text-slate-300">{formatTimer()}</span>
            <div className="flex gap-2">
              <button 
                onClick={() => setTimerRunning(!timerRunning)} 
                className="h-6 w-6 rounded bg-slate-900 border border-slate-800 text-slate-400 hover:text-white flex items-center justify-center transition-colors"
              >
                {timerRunning ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5" />}
              </button>
              <button 
                onClick={() => setSecondsElapsed(0)} 
                className="h-6 w-6 rounded bg-slate-900 border border-slate-800 text-slate-400 hover:text-white flex items-center justify-center transition-colors"
              >
                <RotateCcw className="h-3 w-3" />
              </button>
            </div>
          </div>
        </div>
        
        {/* Resize Handle */}
        <div 
          onMouseDown={handleMouseDown} 
          className="absolute top-0 right-0 w-1 h-full cursor-col-resize hover:bg-sky-400/40 active:bg-sky-400 transition-colors z-30"
        />
      </aside>

      {/* Floating expand button */}
      {sidebarCollapsed && (
        <button 
          onClick={() => setSidebarCollapsed(false)}
          className="fixed bottom-6 left-6 h-10 w-10 rounded-full bg-slate-900 border border-slate-800 text-slate-400 hover:text-white hover:border-slate-700 shadow-2xl flex items-center justify-center z-50 transition-all duration-300"
        >
          <ChevronRight className="h-5 w-5" />
        </button>
      )}

      {/* 2. Main Slides Display Workspace */}
      <div className="flex flex-col h-full flex-1 overflow-hidden">
        {/* Top Header Navigation */}
        <header className="h-16 border-b border-slate-800 bg-slate-950/80 backdrop-blur px-6 flex items-center justify-between z-30 shrink-0 select-none">
          <div className="flex items-center gap-3">
            <div className="text-xs font-bold uppercase tracking-wider bg-sky-500/10 border border-sky-500/20 px-2.5 py-1 rounded text-sky-400">
              {title}
            </div>
            <span className="text-slate-500">|</span>
            <span className="text-xs font-medium text-slate-300">{activeSlideData.title}</span>
          </div>
          
          <div className="flex items-center gap-4">
            
            {/* Live IST Clock */}
            <div className="flex items-center gap-2 bg-slate-900 border border-slate-800 rounded-full px-3.5 py-1 text-slate-300 text-xs font-mono">
              <Clock className="h-3.5 w-3.5 text-sky-400" />
              <span>{istTime}</span>
              <span className="text-[9px] text-slate-500 tracking-wider">IST &bull; INDIA</span>
            </div>
            
            {/* Language Selector Toggle */}
            <div className="relative">
              <select
                value={lang}
                onChange={(e) => setLang(e.target.value)}
                className="bg-slate-900 border border-slate-800 hover:border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-slate-300 outline-none focus:border-sky-400 font-semibold cursor-pointer transition-all"
              >
                <option value="en">🇺🇸 English</option>
                <option value="hi">🇮🇳 हिंदी (Hindi)</option>
              </select>
            </div>

            {/* AI Tutor Launcher Button */}
            {presentationData.aiTutorUrl && (
              <button 
                onClick={() => {
                  const screenWidth = window.screen.availWidth;
                  const screenHeight = window.screen.availHeight;
                  const width = Math.floor(screenWidth / 2);
                  const height = screenHeight;
                  const left = width;
                  const top = 0;
                  const features = `width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes,status=yes`;
                  window.open(presentationData.aiTutorUrl, '_blank', features);
                }}
                title="Launch AI Tutor (Split Screen)"
                className="h-9 px-3 rounded-lg bg-sky-500/10 hover:bg-sky-500/20 border border-sky-500/20 text-sky-400 hover:text-sky-300 flex items-center justify-center gap-1.5 transition-all text-xs font-bold font-sans cursor-pointer"
              >
                <i className="fa-solid fa-robot text-sm"></i>
                <span className="hidden md:inline">AI Tutor</span>
              </button>
            )}

            <button 
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className="h-9 w-9 rounded-lg bg-slate-900 border border-slate-800 text-slate-400 hover:text-white flex items-center justify-center transition-colors animate-fade-up"
            >
              {theme === 'dark' ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
            </button>
            <button 
              onClick={toggleFullscreen}
              className="h-9 w-9 rounded-lg bg-slate-900 border border-slate-800 text-slate-400 hover:text-white flex items-center justify-center transition-colors"
            >
              <Maximize2 className="h-4 w-4" />
            </button>
          </div>
        </header>

        {/* Viewport content area */}
        <main className="flex-1 min-h-0 bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 relative overflow-y-auto p-3 md:p-6 flex items-center justify-center">
          <div className="w-full max-w-4xl mx-auto my-auto flex flex-col justify-center rounded-2xl relative">
            <div className="slide slide-container slide-active my-auto">
              <div className={`bg-slate-900/40 border border-slate-800/50 backdrop-blur rounded-2xl p-5 md:p-7 shadow-2xl animate-fade-up layout-${activeSlideData.layout || 'content'}`}>
                
                {/* Dynamically Render Layout templates */}
                {currentSlide === 0 ? (
                  <div className="text-center py-4">
                    <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-sky-500/10 border border-sky-500/20 text-sky-400 text-[10px] font-bold uppercase tracking-widest mb-4 font-mono">
                      <BookOpen className="h-3 w-3" /> Next Frontier of AI
                    </span>
                    <h1 className="text-4xl md:text-5xl font-bold font-serif mb-3 text-slate-100 tracking-tight">{title}</h1>
                    {(presentationData.subtitle || tagline) && (
                      <p className="text-base italic text-sky-400 mb-4 font-serif">{presentationData.subtitle || tagline}</p>
                    )}
                    {presentationData.description && presentationData.description !== tagline && (
                      <p className="text-xs md:text-sm text-slate-400 max-w-xl mx-auto mb-6 leading-relaxed font-sans">
                        {presentationData.description}
                      </p>
                    )}
                    
                    {/* 3-Column Metadata Card Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 max-w-3xl mx-auto pt-6 border-t border-slate-800/60 text-left mt-8">
                      <div className="p-3.5 rounded-xl bg-slate-900/40 border border-slate-800/40">
                        <span className="text-[10px] uppercase tracking-wider text-slate-500 font-mono font-bold block mb-1">Presented By</span>
                        <div className="flex items-center gap-2 text-slate-200 text-xs font-semibold">
                          <User className="h-4 w-4 text-sky-400" /> {author}
                        </div>
                      </div>
                      <div className="p-3.5 rounded-xl bg-slate-900/40 border border-slate-800/40">
                        <span className="text-[10px] uppercase tracking-wider text-slate-500 font-mono font-bold block mb-1">Date</span>
                        <div className="flex items-center gap-2 text-slate-200 text-xs font-semibold">
                          <Calendar className="h-4 w-4 text-sky-400" /> {date}
                        </div>
                      </div>
                      <div className="p-3.5 rounded-xl bg-slate-900/40 border border-slate-800/40">
                        <span className="text-[10px] uppercase tracking-wider text-slate-500 font-mono font-bold block mb-1">Hosted By</span>
                        <div className="flex items-center gap-2 text-slate-200 text-xs font-semibold">
                          <Award className="h-4 w-4 text-sky-400" /> {affiliation}
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  slideContentNode
                )}

              </div>
            </div>
          </div>
        </main>

        {/* Footer controls */}
        <footer className="h-16 border-t border-slate-800 bg-slate-950/90 backdrop-blur px-6 flex flex-col items-center justify-center z-30 shrink-0 relative select-none">
          <div className="flex items-center justify-between w-full">
            <button 
              id="prev-btn" 
              onClick={previousSlide}
              disabled={currentSlide === 0}
              className="nav-button border border-slate-800 bg-slate-900/50 text-slate-300 font-medium hover:border-slate-700 hover:text-white disabled:opacity-40 transition-all py-1.5 px-4 rounded-lg flex items-center gap-2 text-xs"
            >
              <ChevronLeft className="h-4 w-4" /> Previous
            </button>
            
            {/* Center dot indicators window pagination */}
            <div className="flex flex-col items-center gap-1">
              <div className="flex items-center gap-2" id="jump-dots">
                {renderDots()}
              </div>
              <div id="slide-progress" className="text-[11px] font-mono text-slate-300 font-bold">
                Presenter: {author} {presentationData.version ? `(${presentationData.version.trim()})` : ''} &bull; Slide {currentSlide + 1} of {slides.length}
              </div>
            </div>
            
            <button 
              id="next-btn" 
              onClick={nextSlide}
              disabled={currentSlide === slides.length - 1}
              className="nav-button bg-sky-400 text-slate-950 font-bold hover:bg-sky-500 disabled:opacity-40 transition-all py-1.5 px-4 rounded-lg flex items-center gap-2 text-xs"
            >
              Next <ChevronRight className="h-4 w-4 text-slate-950" />
            </button>
          </div>
        </footer>
      </div>
    </div>
  );
}

export default App;
